 
import { Directive, forwardRef, Input, OnInit } from '@angular/core';
import { AbstractControl, NG_VALIDATORS, ValidationErrors, Validator, ValidatorFn, Validators } from '@angular/forms';
import { EspdValidators } from './validators';

const EQUAL_TO_VALIDATOR: any = {
	provide: NG_VALIDATORS,
	useExisting: forwardRef(() => EqualToValidator),
	multi: true
};

@Directive({
	selector: '[espdEqualTo][formControlName],[espdEqualTo][formControl],[espdEqualTo][ngModel]',
	providers: [EQUAL_TO_VALIDATOR],
	standalone: true
})
export class EqualToValidator implements Validator, OnInit {
	 
	@Input('espdEqualTo') equalTo?: AbstractControl;

	private validator: ValidatorFn = Validators.nullValidator;

	public ngOnInit(): void {
		if (this.equalTo) {
			this.validator = EspdValidators.equalTo(this.equalTo);
		}
	}

	public validate(c: AbstractControl): ValidationErrors | null {
		return this.validator(c);
	}
}