import { HttpClient, HttpHeaders } from '@angular/common/http';
import {
	AbstractControl,
	AsyncValidatorFn,
	UntypedFormArray,
	UntypedFormGroup,
	ValidationErrors,
	ValidatorFn, Validators
} from '@angular/forms';
import { ServiceLocator } from 'espd-common/utils';
import { BehaviorSubject, Observable, of } from 'rxjs';
import {
	catchError,
	debounceTime,
	distinctUntilChanged, first, map,
	switchMap
} from 'rxjs/operators';


export class EspdValidators {
	public static readonly uniqueKeyPattern: ValidatorFn = Validators.pattern(new RegExp('^[a-z0-9\\-]+$'));
	public static readonly hexColorPattern: ValidatorFn = Validators.pattern(/^#[A-Fa-f0-9]{6}$/);

	public static equalTo(equalControl: AbstractControl): ValidatorFn {
		let subscribe = false;

		return (control: AbstractControl): ValidationErrors | null => {
			if (!subscribe) {
				subscribe = true;
				equalControl.valueChanges.subscribe(() => {
					control.updateValueAndValidity();
				});
			}

			const v: string = control.value;

			return equalControl.value === v ? null : { equalTo: { control: equalControl, value: equalControl.value } };
		};
	}

	public static minDate(minDate: Date): ValidatorFn {
		return (control: AbstractControl<Date | null>): ValidationErrors | null => {
			const date = control.value;
			if (!date || date.getTime() >= minDate.getTime()) {
				return null;
			} else {
				return { 'min-date': { value: control.value, expected: minDate } };
			}
		};
	}

	public static unique(url: string, entityId: number | null): AsyncValidatorFn {

		const http: HttpClient | undefined = ServiceLocator.get(HttpClient);

		return AsyncObservableValidator.create(value => {
			const data: any = { value, entityId };
			if (http) {
				return http.post<boolean>(url, JSON.stringify(data), {
					headers: new HttpHeaders({
						'Content-Type': 'application/json',
						'X-Requested-With': 'XMLHttpRequest'
					})
				}).pipe(
					catchError(() => of(true)),
					map((response: boolean) => !response ? { unique: true } : null)
				);
			} else {
				return of(null);
			}
		});
	}

	public static url(): ValidatorFn {
		function doValidate(control: AbstractControl): ValidationErrors | null {
			if (Validators.required(control)) {
				return null;
			}

			const v: string = control.value;
			const regEx = /^(?:(?:(?:https?|ftp):)?\/\/)(?:\S+(?::\S*)?@)?(?:(?!(?:10|127)(?:\.\d{1,3}){3})(?!(?:169\.254|192\.168)(?:\.\d{1,3}){2})(?!172\.(?:1[6-9]|2\d|3[0-1])(?:\.\d{1,3}){2})(?:[1-9]\d?|1\d\d|2[01]\d|22[0-3])(?:\.(?:1?\d{1,2}|2[0-4]\d|25[0-5])){2}(?:\.(?:[1-9]\d?|1\d\d|2[0-4]\d|25[0-4]))|(?:(?:[a-z\u00a1-\uffff0-9]-*)*[a-z\u00a1-\uffff0-9]+)(?:\.(?:[a-z\u00a1-\uffff0-9]-*)*[a-z\u00a1-\uffff0-9]+)*(?:\.(?:[a-z\u00a1-\uffff]{2,})).?)(?::\d{2,5})?(?:[/?#]\S*)?$/i;
			return regEx.test(v) ? null : { url: true };
		}
		return doValidate;
	}

	public static conditional(conditionalFn: (c: AbstractControl) => boolean, validator: ValidatorFn | null): ValidatorFn {
		function doValidate(control: AbstractControl): ValidationErrors | null {
			revalidateOnChanges(control);

			if (conditionalFn(control)) {
				return validator?.(control) ?? null;
			} else {
				return null;
			}
		}
		return doValidate;
	}

	public static arrayMaxLength(max: number): ValidatorFn {
		return (control: AbstractControl) => {
			if (!(control instanceof UntypedFormArray)) return null;
			return control.length > max ? { arrayMaxLength: true } : null;
		};
	}
}

/**
 * Async validator that debounces
 */
class AsyncObservableValidator {
	public static create(callback: (value: any) => Observable<ValidationErrors | null>, debounceTimeMs = 1000): AsyncValidatorFn {
		const valueSubject = new BehaviorSubject<any>(null);
		const valueObservable: Observable<any> = valueSubject.asObservable();

		return (control: AbstractControl): Observable<ValidationErrors | null> => {
			valueSubject.next(control.value);
			return valueObservable.pipe(
				debounceTime(debounceTimeMs),
				switchMap(value => callback(value)),
				first());
		};
	}
}

const revalidateOnChanges = (control: AbstractControl): void => {
	if (control?.parent && !(control as any).revalidateOnChanges) {
		(control as any).revalidateOnChanges = true;

		let root: UntypedFormGroup | UntypedFormArray = control.parent;
		while (root.parent) {
			root = root.parent;
		}

		root.valueChanges
			.pipe(distinctUntilChanged((a: any, b: any) => equals(a, b)))
			.subscribe(() => {
				control.updateValueAndValidity();
			});

		control.updateValueAndValidity();
	}
};

const equals = (x: any, y: any) => {
	if (x === y) { return true; }
	// if both x and y are null or undefined and exactly the same

	if (!(x instanceof Object) || !(y instanceof Object)) { return false; }
	// if they are not strictly equal, they both need to be Objects

	if (x.constructor !== y.constructor) { return false; }
	// they must have the exact same prototype chain, the closest we can do is
	// test there constructor.

	for (const p in x) {
		if (!Object.prototype.hasOwnProperty.call(x, p)) { continue; }
		// other properties were tested using x.constructor === y.constructor

		if (!Object.prototype.hasOwnProperty.call(y, p)) { return false; }
		// allows to compare x[ p ] and y[ p ] when set to undefined

		if (x[p] === y[p]) { continue; }
		// if they have the same strict value or identity then they are equal

		if (typeof (x[p]) !== 'object') { return false; }
		// Numbers, Strings, Functions, Booleans must be strictly equal

		if (!equals(x[p], y[p])) { return false; }
		// Objects and Arrays must be tested recursively
	}

	for (const p in y) {
		if (Object.prototype.hasOwnProperty.call(y, p) && !Object.prototype.hasOwnProperty.call(x, p)) { return false; }
		// allows x[ p ] to be set to undefined
	}
	return true;
};